static int find(uint32_t c) {
    int lo=0, hi=sizeof(points)/sizeof(points[0])-1;
    while(lo<=hi){int mid=(lo+hi)/2; if(points[mid]==c)return mid; if(points[mid]<c)lo=mid+1;else hi=mid-1;}
    return -1;
}
static bool describe(const lv_font_t *font, lv_font_glyph_dsc_t *d, uint32_t c, uint32_t next) {
    (void)font;(void)next;
    if(c<32)return false;
    if(find(c)<0)c='?';
    d->adv_w=c<127?6:12;d->box_w=d->adv_w;d->box_h=12;
    d->ofs_x=0;d->ofs_y=0;d->bpp=1;return true;
}
static const uint8_t *bitmap(const lv_font_t *font,uint32_t c){
    (void)font;int index=find(c);if(index<0)index=find('?');return pixels+index*18;
}
